package com.productionhouse.crm.mediahouse.media.service;
import com.productionhouse.crm.auth.api.ApiException;import com.productionhouse.crm.mediahouse.media.dto.*;import com.productionhouse.crm.mediahouse.media.entity.MediaAsset;import com.productionhouse.crm.mediahouse.media.repository.MediaAssetRepository;import com.productionhouse.crm.task5.util.Task5Paging;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class MediaAssetService{
private final MediaAssetRepository repo;public MediaAssetService(MediaAssetRepository repo){this.repo=repo;}
@Transactional(readOnly=true) public Page<MediaAssetResponse> list(String q,String type,String status,String projectRef,int page,int size,String sort,String direction){String field=Set.of("name","status","createdAt","updatedAt","assetType").contains(sort)?sort:"createdAt";Sort order=Sort.by("asc".equalsIgnoreCase(direction)?Sort.Direction.ASC:Sort.Direction.DESC,field);var results=repo.findAll(order).stream().filter(e->blank(q)||contains(e.getName(),q)||contains(e.getDescription(),q)).filter(e->blank(type)||type.equalsIgnoreCase(e.getAssetType())).filter(e->blank(status)||status.equalsIgnoreCase(e.getStatus())).filter(e->blank(projectRef)||projectRef.equals(e.getProjectRef())).map(this::response).toList();return Task5Paging.page(results,page,size);}
@Transactional(readOnly=true) public MediaAssetResponse get(Long id){return response(find(id));}
@Transactional public MediaAssetResponse create(MediaAssetRequest r){return response(save(new MediaAsset(),r));}
@Transactional public MediaAssetResponse update(Long id,MediaAssetRequest r){return response(save(find(id),r));}
@Transactional public void delete(Long id){repo.delete(find(id));}
private MediaAsset find(Long id){return repo.findById(id).orElseThrow(()->ApiException.notFound("Media asset not found."));}
private MediaAsset save(MediaAsset e,MediaAssetRequest r){e.setName(r.name().trim());e.setDescription(clean(r.description()));e.setProjectRef(clean(r.projectRef()));e.setAssetType(r.assetType().trim().toUpperCase(Locale.ROOT));e.setStatus(r.status().trim().toUpperCase(Locale.ROOT));e.setStorageReference(clean(r.storageReference()));e.setFormat(clean(r.format()));e.setSizeBytes(r.sizeBytes());e.setDurationSeconds(r.durationSeconds());e.setNotes(clean(r.notes()));e.setActive(r.active()==null||r.active());return repo.save(e);}
private MediaAssetResponse response(MediaAsset e){return new MediaAssetResponse(e.getId(),e.getName(),e.getDescription(),e.getProjectRef(),e.getAssetType(),e.getStatus(),e.getStorageReference(),e.getFormat(),e.getSizeBytes(),e.getDurationSeconds(),e.getNotes(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());}
private boolean blank(String x){return x==null||x.isBlank();}private boolean contains(String x,String q){return x!=null&&x.toLowerCase(Locale.ROOT).contains(q.trim().toLowerCase(Locale.ROOT));}private String clean(String x){return x==null||x.isBlank()?null:x.trim();}}

